python3 << 'EOF'
from openpyxl import load_workbook
wb = load_workbook('sales_data.xlsx')
print('Sheets:', wb.sheetnames)
for name in wb.sheetnames:
    ws = wb[name]
    print(f'\nSheet: {name}, dims: {ws.dimensions}, max_row: {ws.max_row}, max_col: {ws.max_column}')
    for row in ws.iter_rows():
        for cell in row:
            if cell.value is not None:
                print(f'{cell.coordinate}: {repr(cell.value)} (type={cell.data_type})')
EOF

